pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address depositor, address owner) public {
        vm.assume(depositor != address(c));
        vm.assume(owner != address(0));
        vm.assume(amount > 0 && amount <= depositor.balance + 1e30);
        vm.assume(owner != address(c));

        // make `owner` the contract owner by deploying? owner is set to deployer (this test contract)
        // instead treat the test contract as owner; use it to trigger withdrawAll
        vm.assume(depositor != address(this));

        amount = bound(amount, 1, 1 ether);

        // fund the contract through its payable fallback via a low-level call (no code needed)
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "deposit failed");

        uint256 beforeBalance = address(c).balance;
        require(beforeBalance == amount, "balance mismatch");
        uint256 ownerBefore = address(this).balance;

        // owner (the deployer = this test contract) withdraws everything
        c.withdrawAll();

        uint256 ownerAfter = address(this).balance;
        uint256 contractAfter = address(c).balance;

        // General rule: withdrawAll must move the FULL balance to the owner:
        // owner's gain equals the balance c held before, and c keeps nothing.
        assertTrue(
            ownerAfter - ownerBefore == beforeBalance && contractAfter == 0,
            "withdrawAll must transfer entire balance to owner"
        );
    }
}

