pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Keep amount admissible: a strictly positive deposit that we can fund
        amount = bound(amount, 1, 1 ether);

        // Fund the contract via its payable fallback (depositsCount increments)
        vm.deal(address(this), amount);
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded, "deposit failed");

        // Owner (msg.sender at deployment == test contract) withdraws ALL twice.
        // In P: first call drains the full balance, second call transfers 0 and
        //       the contract ends at zero balance.
        // In M: each call withdraws only half, so a positive remainder survives
        //       both calls.
        vm.prank(address(this));
        c.withdrawAll();
        vm.prank(address(this));
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}

