contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint256 balance, uint256 value) public {
        address actor = address(uint160(bound(seed, 1, type(uint160).max)));
        balance = bound(balance, 1, 1e30);
        value = bound(value, 0, balance - 1); // admissible: any amount below the contract balance
        vm.deal(address(c), balance);
        uint256 before = actor.balance;
        vm.prank(actor);
        c.withdraw(value);
        // General rule: the caller is paid exactly the requested amount, never more.
        assertTrue(actor.balance - before == value);
    }
}

